// Convenience aliases over the OpenAPI-generated schema (src/api/schema.d.ts,
// regenerated by `npm run generate` from the server's exported openapi.json).
import type { components } from "./schema";

export type Session = components["schemas"]["Session"];
export type AdapterInfo = components["schemas"]["AdapterInfo"];
export type ModelInfo = components["schemas"]["ModelInfo"];
export type ProdeoEvent = components["schemas"]["Event"];
export type SessionState = Session["state"];
export type Interaction = components["schemas"]["Interaction"];
export type AnswerRequest = components["schemas"]["AnswerRequest"];
export type QuestionGroup = components["schemas"]["QuestionGroup"];
export type QuestionOption = components["schemas"]["QuestionOption"];
export type LaunchRequest = components["schemas"]["LaunchRequest"];
export type ExtensionSummary = components["schemas"]["ExtensionSummary"];
export type ExtensionDetail = components["schemas"]["ExtensionDetail"];
export type ExtensionConfig = components["schemas"]["ExtensionConfig"];
export type CatalogEntry = components["schemas"]["CatalogEntry"];
export type Catalog = components["schemas"]["Catalog"];
export type InstallResult = components["schemas"]["InstallResult"];
export type ExtensionSettings = components["schemas"]["ExtensionSettings"];
export type AppStatus = components["schemas"]["AppStatus"];
export type AssetStatus = components["schemas"]["AssetStatus"];
export type AssetResult = components["schemas"]["AssetResult"];
export type EnvironmentCheck = components["schemas"]["EnvironmentCheck"];
export type EnvironmentReport = components["schemas"]["EnvironmentReport"];
export type ContextUsage = components["schemas"]["ContextUsage"];
export type HealthResponse = components["schemas"]["HealthResponse"];
export type RestartResponse = components["schemas"]["RestartResponse"];
export type DirectoryEntry = components["schemas"]["DirectoryEntry"];
export type DirectoryListing = components["schemas"]["DirectoryListing"];

export const ACTIVE_STATES: readonly string[] = [
  "running",
  "waiting_on_user",
  "starting",
  "discovered",
];

export function isActive(state: string): boolean {
  return ACTIVE_STATES.includes(state);
}
